<?php $pageTitle='Evaluación';$pageSubtitle=$eval['titulo_curso']??'';require __DIR__.'/../partials/header.php'; ?><div class="panel"><h2><?=htmlspecialchars($eval['titulo_evaluacion'])?></h2><p><?=htmlspecialchars($eval['descripcion_evaluacion'])?></p></div><?php if($resultado): ?><div class="success">Último resultado: <strong><?=htmlspecialchars($resultado['calificacion'])?> / 5</strong> — <?=((int)$resultado['aprobado']?'Aprobado':'No aprobado')?></div><?php endif; ?><?php if(!$resultado && !$preguntas): ?><div class="empty">Esta evaluación todavía no tiene preguntas.</div><?php elseif(!$resultado): ?><form method="post" action="index.php?route=responder-evaluacion"><input type="hidden" name="evaluacion" value="<?=$id?>"><?php foreach($preguntas as $i=>$p): ?><div class="card" style="margin:15px 0"><h3><?=($i+1).'. '.htmlspecialchars($p['pregunta'])?></h3><?php foreach($p['respuestas'] as $r): ?><label style="display:block;padding:9px"><input type="radio" name="p_<?=$p['id_pregunta']?>" value="<?=$r['id_respuesta']?>" required> <?=htmlspecialchars($r['respuesta'])?></label><?php endforeach; ?></div><?php endforeach; ?><button class="btn btn-primary">Enviar evaluación</button></form><?php endif; ?><?php require __DIR__.'/../partials/footer.php'; ?>
